  const itemPlan=refundItems(s,cid,v,a);const giftBalances=new Map();for(const l of s.ledger.filter(l=>l.visitId===v.id)){if(l.type==='gift-settled')giftBalances.set(l.giftCardId,(giftBalances.get(l.giftCardId)||0)+l.amountMinor);if(l.type==='gift-refunded')giftBalances.set(l.giftCardId,(giftBalances.get(l.giftCardId)||0)-l.amountMinor);}
